using sv_2a4db9df878b477e9d8112ae6e6f7272.Client.Services;

namespace sv_2a4db9df878b477e9d8112ae6e6f7272.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            DateTimeOffset.UtcNow.AddDays(2),
            [
                new StatusUpdate("Package picked up", DateTimeOffset.UtcNow.AddDays(-3)),
                new StatusUpdate("Arrived at sorting facility", DateTimeOffset.UtcNow.AddDays(-2)),
                new StatusUpdate("In transit to destination", DateTimeOffset.UtcNow.AddDays(-1)),
            ]),
        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            DateTimeOffset.UtcNow.AddDays(-1),
            [
                new StatusUpdate("Package picked up", DateTimeOffset.UtcNow.AddDays(-5)),
                new StatusUpdate("In transit", DateTimeOffset.UtcNow.AddDays(-4)),
                new StatusUpdate("Out for delivery", DateTimeOffset.UtcNow.AddDays(-1)),
                new StatusUpdate("Delivered", DateTimeOffset.UtcNow.AddDays(-1).AddHours(3)),
            ]),
        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            DateTimeOffset.UtcNow.AddDays(5),
            [
                new StatusUpdate("Order placed", DateTimeOffset.UtcNow.AddHours(-6)),
                new StatusUpdate("Label created", DateTimeOffset.UtcNow.AddHours(-2)),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

